// נוצר אוטומטית ע"י scripts/build-webui.mjs. אין לערוך ידנית.
export default "<!doctype html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#3b2bd6\">\n<title>DALI PAY</title>\n<style>\n:root{\n  --y1:#ffe55c;--y2:#ffb800;--p1:#7c4dff;--p2:#4a2bd6;--b1:#3aa8ff;--b2:#6a5cff;\n  --ink:#1c1450;--glass:rgba(255,255,255,.16);--green:#19c37d;--red:#ff4d6d;\n}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;height:100%}\nbody{\n  font-family:\"Rubik\",\"Heebo\",system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;\n  color:#fff;background:linear-gradient(170deg,#38b6ff 0%,#6a5cff 45%,#8a3cff 100%) fixed;\n  overflow-x:hidden;-webkit-user-select:none;user-select:none;\n}\nbody:before,body:after{content:\"\";position:fixed;border-radius:50%;filter:blur(60px);opacity:.55;z-index:0;pointer-events:none}\nbody:before{width:260px;height:260px;background:#00e0ff;top:-60px;left:-80px;animation:drift 9s ease-in-out infinite alternate}\nbody:after{width:300px;height:300px;background:#ff5de0;bottom:-100px;right:-100px;animation:drift 11s ease-in-out infinite alternate-reverse}\n@keyframes drift{to{transform:translate(40px,30px) scale(1.15)}}\nbutton{font:inherit;color:inherit;border:0;background:none;cursor:pointer}\ninput,select,textarea{font:inherit}\n\n/* ---------- splash ---------- */\n#splash{position:fixed;inset:0;z-index:50;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;\n  background:linear-gradient(170deg,#38b6ff,#6a5cff 50%,#8a3cff);transition:opacity .7s ease,visibility 0s .7s}\n#splash .sbg{position:absolute;inset:-10%;background-size:cover;background-position:center;filter:blur(28px) saturate(1.3);opacity:.55;transform:scale(1.1);animation:sbg 6s ease-in-out infinite alternate}\n@keyframes sbg{to{transform:scale(1.22) rotate(2deg)}}\n#splash .rays{position:absolute;width:170vmax;height:170vmax;left:50%;top:44%;margin:-85vmax 0 0 -85vmax;\n  background:repeating-conic-gradient(from 0deg,rgba(255,255,255,.16) 0 8deg,rgba(255,255,255,0) 8deg 22deg);\n  -webkit-mask:radial-gradient(circle,#000 0,transparent 62%);mask:radial-gradient(circle,#000 0,transparent 62%);animation:spin 30s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n#splash .shero{position:relative;width:min(94vw,74vh);aspect-ratio:1;border-radius:36px;box-shadow:0 30px 80px rgba(30,10,120,.6),0 0 0 4px rgba(255,255,255,.45),0 0 60px rgba(120,240,255,.55);\n  animation:heroIn 1.1s cubic-bezier(.18,1.3,.4,1) both,float 4.5s ease-in-out 1.1s infinite}\n@keyframes heroIn{0%{transform:perspective(900px) scale(.55) rotateX(18deg) rotate(-6deg);opacity:0;filter:blur(8px)}60%{opacity:1;filter:blur(0)}100%{transform:none}}\n#splash .tw{position:absolute;color:#fff;font-size:22px;text-shadow:0 0 12px #fff,0 0 24px #9ff;opacity:0;animation:tw 2.4s ease-in-out infinite}\n@keyframes tw{0%,100%{opacity:0;transform:scale(.4) rotate(0)}50%{opacity:1;transform:scale(1.15) rotate(90deg)}}\n#splash p{position:relative;margin:22px 0 0;font-weight:900;font-size:16px;letter-spacing:.3px;text-shadow:0 2px 8px rgba(30,10,120,.5);animation:rise .8s .5s both}\n#splash.out{opacity:0;visibility:hidden;pointer-events:none}\n#splash.out .shero{animation:heroOut .7s cubic-bezier(.5,0,.75,0) both}\n@keyframes heroOut{to{transform:scale(1.25) translateY(-30px);opacity:0;filter:blur(6px)}}\n@keyframes pop{from{transform:scale(.6) rotate(-4deg);opacity:0}}\n@keyframes float{50%{transform:translateY(-8px)}}\n.dots{position:relative;display:flex;gap:7px;margin-top:12px}\n.dots i{width:9px;height:9px;border-radius:50%;background:#fff;opacity:.4;animation:blink 1s infinite}\n.dots i:nth-child(2){animation-delay:.2s}.dots i:nth-child(3){animation-delay:.4s}\n@keyframes blink{50%{opacity:1;transform:translateY(-4px)}}\n\n/* ---------- layout ---------- */\n#app{position:relative;z-index:1;max-width:520px;margin:0 auto;padding:calc(env(safe-area-inset-top) + 12px) 14px calc(env(safe-area-inset-bottom) + 110px)}\n.banner{position:relative;border-radius:26px;overflow:hidden;box-shadow:0 10px 30px rgba(30,10,120,.4),0 0 0 3px rgba(255,255,255,.4)}\n#app>*{opacity:0}\n#app.show>*{animation:enter .75s cubic-bezier(.2,1.1,.3,1) both}\n#app.show>:nth-child(2){animation-delay:.08s}#app.show>:nth-child(3){animation-delay:.16s}#app.show>:nth-child(4){animation-delay:.22s}#app.show>:nth-child(n+5){animation-delay:.28s}\n@keyframes enter{from{opacity:0;transform:translateY(34px) scale(.96)}to{opacity:1;transform:none}}\n.banner img{display:block;width:100%;height:auto}\n.who{position:absolute;top:8px;left:8px;background:rgba(255,255,255,.88);color:var(--ink);border-radius:999px;padding:6px 12px;font-weight:800;font-size:12px;box-shadow:0 4px 10px rgba(0,0,0,.2)}\n@keyframes rise{from{transform:translateY(18px);opacity:0}}\n\n.stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}\n.stat{position:relative;border-radius:24px;overflow:hidden;min-height:128px;padding:14px 14px 12px;color:#fff;isolation:isolate;\n  display:flex;flex-direction:column;justify-content:space-between;box-shadow:0 12px 26px rgba(30,10,120,.32),inset 0 0 0 2px rgba(255,255,255,.35)}\n.stat.owe{background:linear-gradient(145deg,#ff9a8b 0%,#ff4f81 45%,#c81d77 100%);box-shadow:0 12px 26px rgba(200,29,119,.38),inset 0 0 0 2px rgba(255,255,255,.4)}\n.stat.owed{background:linear-gradient(145deg,#7cf5d0 0%,#14c6a0 45%,#0b8bb0 100%);box-shadow:0 12px 26px rgba(11,139,176,.38),inset 0 0 0 2px rgba(255,255,255,.4)}\n.stat:before{content:\"\";position:absolute;width:150px;height:150px;border-radius:50%;background:rgba(255,255,255,.16);top:-60px;left:-50px;z-index:-1}\n.stat:after{content:\"\";position:absolute;width:90px;height:90px;border-radius:50%;background:rgba(255,255,255,.12);bottom:-34px;right:-20px;z-index:-1}\n.stat .shine{position:absolute;inset:0;z-index:-1;background:linear-gradient(115deg,transparent 30%,rgba(255,255,255,.35) 48%,transparent 66%);transform:translateX(-120%);animation:shine 7s ease-in-out 2s infinite}\n.stat.owed .shine{animation-delay:3.2s}\n@keyframes shine{0%,72%{transform:translateX(-120%)}90%,100%{transform:translateX(120%)}}\n.stat .top{display:flex;align-items:center;gap:8px}\n.stat .ico{width:34px;height:34px;border-radius:12px;display:grid;place-items:center;font-size:18px;font-weight:900;background:rgba(255,255,255,.28);box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.5)}\n.stat small{display:block;font-weight:800;font-size:14px;letter-spacing:.2px;opacity:.97}\n.stat b{display:block;font-size:34px;font-weight:900;line-height:1;letter-spacing:-.5px;text-shadow:0 3px 10px rgba(60,0,60,.25);direction:ltr;text-align:right;white-space:nowrap}\n.stat.bump{animation:bump .55s cubic-bezier(.3,1.6,.5,1)}\n@keyframes bump{40%{transform:scale(1.06)}}\n.stat.total{grid-column:1/-1;min-height:84px;flex-direction:row;align-items:center;background:linear-gradient(100deg,#fff07a,#ffd02a 50%,#ffae00);color:var(--ink);box-shadow:0 10px 22px rgba(255,170,0,.42),inset 0 0 0 2px rgba(255,255,255,.75)}\n.stat.total:before{background:rgba(255,255,255,.3)}\n.stat.total b{font-size:32px;text-shadow:none}\n.stat.total small{font-size:14px;margin-bottom:4px}\n.stat.total .coin{font-size:36px;animation:coin 3.2s ease-in-out infinite}\n@keyframes coin{0%,100%{transform:translateY(0) rotateY(0)}50%{transform:translateY(-6px) rotateY(180deg)}}\n.pos{color:#0b7d4d}.neg{color:#c01540}\n\n.actions{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:14px}\n.big{position:relative;border-radius:22px;padding:0;overflow:hidden;background:linear-gradient(180deg,#fff7b0,#ffd23a 55%,#ffb300);\n  color:var(--ink);font-weight:900;font-size:14px;box-shadow:0 7px 0 #c98400,0 14px 22px rgba(30,10,120,.35);transition:transform .12s,box-shadow .12s}\n.big:active{transform:translateY(5px);box-shadow:0 2px 0 #c98400,0 6px 10px rgba(30,10,120,.3)}\n.big .tile{height:74px;background-size:100% auto;background-position:top;border-bottom:3px solid #ffb300}\n.big span{display:block;padding:8px 2px 10px}\n\nh2{display:flex;align-items:center;gap:8px;margin:22px 4px 10px;font-size:18px;font-weight:900;text-shadow:0 2px 6px rgba(30,10,120,.4)}\nh2 .ic{width:34px;height:34px;border-radius:10px;background-size:cover;background-position:top;box-shadow:0 0 0 2px rgba(255,255,255,.6)}\nh2 em{margin-inline-start:auto;font-style:normal;font-size:12px;background:rgba(255,255,255,.22);padding:3px 10px;border-radius:999px}\n\n.card{background:rgba(255,255,255,.95);color:var(--ink);border-radius:20px;padding:13px 14px;margin-bottom:10px;box-shadow:0 8px 18px rgba(30,10,120,.28);animation:rise .4s both;position:relative;overflow:hidden}\n.card:active{transform:scale(.985)}\n.row{display:flex;align-items:center;gap:10px}\n.dir{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;font-size:20px;flex:none}\n.dir.in{background:linear-gradient(135deg,#b6ffdf,#19c37d)}\n.dir.out{background:linear-gradient(135deg,#ffc2cf,#ff4d6d)}\n.grow{flex:1;min-width:0}\n.t{font-weight:900;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.s{font-size:12px;opacity:.65;margin-top:2px;font-weight:600}\n.amt{font-weight:900;font-size:18px;text-align:left;direction:ltr}\n.amt.in{color:#0b9a63}.amt.out{color:#e0294d}\n.bar{height:7px;border-radius:9px;background:#e8e4ff;margin-top:10px;overflow:hidden}\n.bar i{display:block;height:100%;border-radius:9px;background:linear-gradient(90deg,#7c4dff,#3aa8ff);transition:width .5s}\n.badge{font-size:11px;font-weight:800;border-radius:999px;padding:3px 9px;background:#efeaff;color:#5a37d9}\n.badge.ok{background:#d8ffec;color:#0b7d4d}\n\n.empty{text-align:center;color:#fff}\n.empty .pic{width:150px;aspect-ratio:203/150;margin:4px auto 6px;border-radius:20px;background-size:100% auto;background-position:top;box-shadow:0 0 0 3px rgba(255,255,255,.5),0 10px 20px rgba(30,10,120,.35);animation:float 4s ease-in-out infinite}\n.empty b{display:block;font-weight:900;font-size:16px}\n.empty span{font-size:13px;opacity:.85}\n\n.notes{display:flex;gap:10px;overflow-x:auto;padding:18px 6px 14px;margin-top:4px;scroll-snap-type:x mandatory}\n.notes::-webkit-scrollbar{display:none}\n.note{flex:none;width:170px;scroll-snap-align:start;border-radius:6px 6px 22px 6px;padding:14px 13px 12px;color:var(--ink);font-weight:800;font-size:14px;line-height:1.35;box-shadow:0 10px 18px rgba(30,10,120,.35);transform:rotate(-2deg);position:relative;min-height:120px;display:flex;flex-direction:column;justify-content:space-between;animation:rise .4s both}\n.note:nth-child(2n){transform:rotate(2deg)}\n.note .pin{position:absolute;top:-8px;left:50%;margin-left:-11px;font-size:22px;filter:drop-shadow(0 2px 2px rgba(0,0,0,.3))}\n.note small{font-size:11px;opacity:.6;margin-top:8px}\n.n0{background:#fff176}.n1{background:#ffb4e1}.n2{background:#aef0ff}.n3{background:#c8ffb0}\n\n/* ---------- sheet ---------- */\n#scrim{position:fixed;inset:0;background:rgba(15,5,60,.55);backdrop-filter:blur(4px);z-index:30;opacity:0;pointer-events:none;transition:opacity .25s}\n#scrim.on{opacity:1;pointer-events:auto}\n#sheet{position:fixed;left:0;right:0;bottom:0;z-index:31;max-width:520px;margin:0 auto;background:linear-gradient(180deg,#fff,#efeaff);color:var(--ink);\n  border-radius:30px 30px 0 0;padding:10px 18px calc(env(safe-area-inset-bottom) + 20px);transform:translateY(105%);transition:transform .35s cubic-bezier(.2,.9,.3,1);max-height:90vh;overflow:auto;box-shadow:0 -10px 40px rgba(30,10,120,.4)}\n#sheet.on{transform:none}\n#sheet .grab{width:48px;height:5px;border-radius:9px;background:#cfc6ff;margin:0 auto 12px}\n#sheet .hd{display:flex;align-items:center;gap:12px;margin-bottom:12px}\n#sheet .hd .pic{width:74px;aspect-ratio:203/150;border-radius:14px;background-size:100% auto;background-position:top;box-shadow:0 4px 10px rgba(30,10,120,.3);flex:none}\n#sheet h3{margin:0;font-size:20px;font-weight:900}\nlabel{display:block;font-weight:800;font-size:13px;margin:12px 2px 6px}\n.inp{width:100%;border:2px solid #d9d0ff;background:#fff;border-radius:16px;padding:13px 14px;font-size:17px;font-weight:700;color:var(--ink);outline:0;-webkit-user-select:text;user-select:text}\n.inp:focus{border-color:var(--p1);box-shadow:0 0 0 4px rgba(124,77,255,.18)}\n.seg{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.seg button{border-radius:16px;padding:13px 6px;font-weight:900;font-size:14px;background:#fff;border:2px solid #d9d0ff;color:#5a37d9;transition:.15s}\n.seg button.on{background:linear-gradient(135deg,#7c4dff,#3aa8ff);color:#fff;border-color:transparent;box-shadow:0 6px 14px rgba(124,77,255,.4)}\n.cta{width:100%;margin-top:18px;border-radius:20px;padding:16px;font-weight:900;font-size:18px;color:var(--ink);background:linear-gradient(180deg,#fff7b0,#ffd23a 55%,#ffb300);box-shadow:0 6px 0 #c98400,0 12px 20px rgba(255,170,0,.4)}\n.cta:active{transform:translateY(4px);box-shadow:0 2px 0 #c98400}\n.cta.ghost{background:#fff;box-shadow:0 0 0 2px #d9d0ff;color:#5a37d9;margin-top:10px}\n.cta.danger{background:linear-gradient(180deg,#ff8aa0,#ff4d6d);color:#fff;box-shadow:0 6px 0 #b8203f}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.colors{display:flex;gap:10px}\n.colors button{width:40px;height:40px;border-radius:50%;box-shadow:inset 0 0 0 3px rgba(255,255,255,.7),0 3px 8px rgba(0,0,0,.2)}\n.colors button.on{outline:3px solid var(--p1);outline-offset:2px}\n.hist{margin-top:10px;font-size:13px;font-weight:700;opacity:.8}\n.hist div{display:flex;justify-content:space-between;padding:6px 2px;border-bottom:1px dashed #d9d0ff}\n\n#toast{position:fixed;top:calc(env(safe-area-inset-top) + 12px);left:50%;transform:translate(-50%,-140%);z-index:60;background:#fff;color:var(--ink);padding:8px 16px 8px 10px;border-radius:999px;font-weight:900;font-size:14px;display:flex;align-items:center;gap:10px;box-shadow:0 10px 30px rgba(30,10,120,.45);transition:transform .4s cubic-bezier(.2,1.3,.4,1);max-width:92vw}\n#toast.on{transform:translate(-50%,0)}\n#toast i{width:40px;height:30px;border-radius:9px;background-size:100% auto;background-position:top;flex:none}\n\n#who{position:fixed;inset:0;z-index:40;display:none;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:24px;background:linear-gradient(170deg,rgba(56,182,255,.96),rgba(138,60,255,.97));text-align:center}\n#who.on{display:flex}\n#who h1{margin:0 0 6px;font-size:26px;font-weight:900}\n#who .pick{width:min(80vw,300px);border-radius:24px;padding:18px;font-size:22px;font-weight:900;color:var(--ink);background:linear-gradient(180deg,#fff7b0,#ffd23a 55%,#ffb300);box-shadow:0 7px 0 #c98400,0 14px 22px rgba(30,10,120,.4)}\n.mini{font-size:12px;opacity:.85;margin-top:12px}\n\n/* ---------- gate (login / group) ---------- */\n#gate{position:fixed;inset:0;z-index:45;display:none;overflow:auto;background:linear-gradient(170deg,#38b6ff 0%,#6a5cff 45%,#8a3cff 100%)}\n#gate.on{display:block}\n#gate .gbox{max-width:480px;margin:0 auto;padding:calc(env(safe-area-inset-top) + 18px) 18px 40px}\n#gate .ghero{display:block;width:min(70vw,260px);aspect-ratio:1;margin:0 auto 16px;border-radius:30px;box-shadow:0 14px 40px rgba(30,10,120,.5),0 0 0 3px rgba(255,255,255,.4)}\n#gate .card{padding:18px}\n#gate label{margin-top:4px}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:#b9b0e8;margin-inline-start:6px;vertical-align:1px}\n.dot.ok{background:#19c37d;box-shadow:0 0 0 3px rgba(25,195,125,.25)}.dot.bad{background:#ff4d6d;box-shadow:0 0 0 3px rgba(255,77,109,.25)}\n.invite{border:2px dashed #7c4dff}\nbutton:disabled{cursor:default}\n.card,.cta,.note,.who,.seg button,.colors button{transition:transform .16s cubic-bezier(.3,1.5,.5,1)}\n.card:active,.note:active{transform:scale(.97)}\n.cta:active{transform:translateY(4px) scale(.98)}\n.big .tile{transition:transform .35s cubic-bezier(.3,1.6,.5,1)}\n.big:active .tile{transform:scale(1.08) rotate(-2deg)}\n.big.hop .tile{animation:hop .6s cubic-bezier(.3,1.6,.5,1)}\n@keyframes hop{30%{transform:translateY(-6px) scale(1.06) rotate(-3deg)}60%{transform:rotate(2deg)}}\n#sheet.on .hd .pic{animation:charIn .7s cubic-bezier(.2,1.6,.4,1) .12s both,wob 3.5s ease-in-out .9s infinite}\n@keyframes charIn{from{transform:scale(.3) rotate(-14deg);opacity:0}}\n@keyframes wob{0%,100%{transform:rotate(0)}25%{transform:rotate(-3deg) translateY(-2px)}75%{transform:rotate(3deg)}}\n#toast.on i{animation:charIn .6s cubic-bezier(.2,1.6,.4,1) both,wob 1.4s ease-in-out .6s 2}\n.card.fresh{animation:fresh .9s cubic-bezier(.2,1.3,.4,1) both}\n@keyframes fresh{0%{transform:translateX(40px) scale(.9);opacity:0}60%{box-shadow:0 0 0 4px rgba(255,214,58,.9),0 8px 18px rgba(30,10,120,.28)}100%{transform:none;opacity:1}}\n.fx{position:fixed;z-index:70;pointer-events:none;font-size:26px;left:0;top:0;will-change:transform,opacity}\n#cele{position:fixed;inset:0;z-index:65;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none;opacity:0;transition:opacity .25s}\n#cele.on{opacity:1}\n#cele .cpic{width:min(62vw,250px);aspect-ratio:203/150;border-radius:26px;background-size:100% auto;background-position:top;box-shadow:0 18px 50px rgba(30,10,120,.55),0 0 0 4px #fff}\n#cele.on .cpic{animation:celeIn .8s cubic-bezier(.2,1.6,.4,1) both,wob 1.2s ease-in-out .8s}\n#cele b{margin-top:14px;font-size:24px;font-weight:900;text-shadow:0 3px 12px rgba(30,10,120,.6)}\n#cele.on b{animation:celeIn .7s cubic-bezier(.2,1.6,.4,1) .15s both}\n@keyframes celeIn{from{transform:scale(.2) rotate(-12deg);opacity:0}}\n#gate{transition:opacity .45s ease,transform .45s ease}\n#gate.leave{opacity:0;transform:translateY(-24px) scale(1.02)}\n#gate.on .card{animation:enter .7s cubic-bezier(.2,1.1,.3,1) .1s both}\n#gate.on .ghero{animation:heroIn .9s cubic-bezier(.18,1.3,.4,1) both,float 4.5s ease-in-out 1s infinite}\n@media (prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}\n</style>\n</head>\n<body>\n\n<div id=\"splash\"><div class=\"sbg\" data-bg=\"hero\"></div><div class=\"rays\"></div><span class=\"tw\" style=\"top:12%;left:14%\">✦</span><span class=\"tw\" style=\"top:18%;right:12%;animation-delay:.7s\">✦</span><span class=\"tw\" style=\"bottom:22%;left:10%;animation-delay:1.3s;font-size:16px\">✦</span><span class=\"tw\" style=\"bottom:16%;right:16%;animation-delay:.35s;font-size:28px\">✦</span><span class=\"tw\" style=\"top:8%;left:52%;animation-delay:1.8s;font-size:14px\">✦</span><img class=\"shero\" data-src=\"hero\" alt=\"DALI PAY\"><p>טוען את החשבונות…</p><div class=\"dots\"><i></i><i></i><i></i></div></div>\n\n<div id=\"gate\"><div class=\"gbox\"><img class=\"ghero\" data-src=\"hero\" alt=\"\"><div class=\"card\" id=\"gateCard\"></div></div></div>\n\n<div id=\"app\">\n  <div class=\"banner\"><img data-src=\"banner\" alt=\"DALI PAY – ניהול חובות ומוצרים\"><button class=\"who\" id=\"whoBtn\"></button></div>\n\n  <div class=\"stats\">\n    <div class=\"stat owe\" id=\"cOwe\"><i class=\"shine\"></i><div class=\"top\"><span class=\"ico\">↗</span><small>אני חייב</small></div><b id=\"sIowe\">₪0</b></div>\n    <div class=\"stat owed\" id=\"cOwed\"><i class=\"shine\"></i><div class=\"top\"><span class=\"ico\">↙</span><small>חייבים לי</small></div><b id=\"sOwed\">₪0</b></div>\n    <div class=\"stat total\" id=\"cBal\"><div style=\"flex:1\"><small>יתרה כוללת</small><b id=\"sBal\">₪0</b></div><span class=\"coin\">🪙</span></div>\n  </div>\n\n  <div class=\"actions\">\n    <button class=\"big\" id=\"bDebt\"><div class=\"tile\" data-bg=\"opendebt\"></div><span>הוסף חוב</span></button>\n    <button class=\"big\" id=\"bProd\"><div class=\"tile\" data-bg=\"addprod\"></div><span>הוסף מוצר</span></button>\n    <button class=\"big\" id=\"bNote\"><div class=\"tile\" data-bg=\"notes\"></div><span>נעץ פתק</span></button>\n  </div>\n\n  <div id=\"notesWrap\"></div>\n\n  <h2><span class=\"ic\" data-bg=\"opendebt\"></span>חובות פתוחים<em id=\"cDebts\">0</em></h2>\n  <div id=\"debts\"></div>\n\n  <h2><span class=\"ic\" data-bg=\"prodlist\"></span>מוצרים בדרך<em id=\"cProds\">0</em></h2>\n  <div id=\"prods\"></div>\n</div>\n\n<div id=\"scrim\"></div>\n<div id=\"sheet\"></div>\n<div id=\"cele\"><div class=\"cpic\"></div><b></b></div>\n<div id=\"toast\"><i></i><span></span></div>\n\n<script>\n(function(){\n'use strict';\nvar IMG={\"addfriend\":\"data:image/jpeg;base64,\",\"addprod\":\"data:image/jpeg;base64,\",\"backup\":\"data:image/jpeg;base64,\",\"banner\":\"data:image/jpeg;base64,\",\"close\":\"data:image/jpeg;base64,\",\"closeddebt\":\"data:image/jpeg;base64,\",\"csv\":\"data:image/jpeg;base64,\",\"cycle\":\"data:image/jpeg;base64,\",\"delprod\":\"data:image/jpeg;base64,\",\"friends\":\"data:image/jpeg;base64,\",\"full\":\"data:image/jpeg;base64,\",\"hero\":\"data:image/jpeg;base64,\",\"history\":\"data:image/jpeg;base64,\",\"iowe\":\"data:image/jpeg;base64,\",\"myprod\":\"data:image/jpeg;base64,\",\"notes\":\"data:image/jpeg;base64,\",\"opendebt\":\"data:image/jpeg;base64,\",\"owedme\":\"data:image/jpeg;base64,\",\"prodlist\":\"data:image/jpeg;base64,\",\"product\":\"data:image/jpeg;base64,\",\"remprod\":\"data:image/jpeg;base64,\",\"search\":\"data:image/jpeg;base64,\",\"settings\":\"data:image/jpeg;base64,\",\"summary\":\"data:image/jpeg;base64,\",\"transfer\":\"data:image/jpeg;base64,\",\"xls\":\"data:image/jpeg;base64,\"};\nvar HIDE_KEY='dalipay.hidden.notes', CACHE_PREFIX='dalipay.cache.';\nvar S={fresh:{},uid:null,email:null,mem:null,members:[],debts:[],pays:[],prods:[],msgs:[],sync:null};\n\n/* ---------- helpers ---------- */\nfunction $(id){return document.getElementById(id)}\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}\nfunction r2(n){return Math.round((Number(n)+Number.EPSILON)*100)/100}\nfunction money(n){n=r2(n);return '₪'+n.toLocaleString('he-IL',{maximumFractionDigits:2})}\nfunction pad(n){return ('0'+n).slice(-2)}\nfunction ymd(iso){var d=iso?new Date(iso):new Date();return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}\nfunction fdate(iso){if(!iso)return '';var d=new Date(iso);return pad(d.getDate())+'/'+pad(d.getMonth()+1)+'/'+String(d.getFullYear()).slice(2)}\nfunction img(n){return 'var(--i-'+n+')'}\nfunction lsGet(k){try{return JSON.parse(localStorage.getItem(k))}catch(e){return null}}\nfunction lsSet(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}\nObject.keys(IMG).forEach(function(k){document.documentElement.style.setProperty('--i-'+k,'url('+IMG[k]+')')});\n[].forEach.call(document.querySelectorAll('[data-bg]'),function(e){e.style.backgroundImage=img(e.getAttribute('data-bg'))});\n[].forEach.call(document.querySelectorAll('[data-src]'),function(e){e.src=IMG[e.getAttribute('data-src')]||''});\n\n/* ---------- bridge to native ---------- */\nvar pend={},seq=0;\nfunction call(op,args,ms){\n  return new Promise(function(res,rej){\n    if(!window.ReactNativeWebView)return rej(new Error('נא לפתוח את DALI PAY מתוך האפליקציה במכשיר'));\n    var id=++seq,t=setTimeout(function(){delete pend[id];rej(new Error('אין תגובה מהשרת. בדוק חיבור לאינטרנט'))},ms||20000);\n    pend[id]={res:res,rej:rej,t:t};\n    window.ReactNativeWebView.postMessage(JSON.stringify({id:id,op:op,args:args||{}}));\n  });\n}\nwindow.__fromNative=function(m){\n  if(typeof m==='string')m=JSON.parse(m);\n  if(m.event==='changed'){queueLoad();return}\n  if(m.event==='back'){onBack();return}\n  if(m.event==='resume'){queueLoad();return}\n  var p=pend[m.id];if(!p)return;clearTimeout(p.t);delete pend[m.id];\n  if(m.ok)p.res(m.result);else p.rej(new Error(m.error||'שגיאה'));\n};\nfunction onBack(){\n  if($('sheet').classList.contains('on')){closeSheet();return}\n  call('exit',{}).catch(function(){});\n}\n\n/* ---------- toast / sheet ---------- */\nvar tt;function toast(msg,pic){var t=$('toast');t.querySelector('i').style.backgroundImage=img(pic||'close');t.querySelector('span').textContent=msg;t.classList.remove('on');void t.offsetWidth;t.classList.add('on');clearTimeout(tt);tt=setTimeout(function(){t.classList.remove('on')},2600)}\n/* ---------- motion & effects ---------- */\nvar RM=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);\nfunction countTo(el,val,fmt){\n  var from=el._v==null?0:el._v,first=el._v==null;el._v=val;\n  if(!first&&from!==val){var c=el.closest('.stat');if(c){c.classList.remove('bump');void c.offsetWidth;c.classList.add('bump')}}\n  if(RM||from===val){el.textContent=fmt(val);return}\n  var t0=performance.now(),d=first?1100:700;\n  (function f(t){var k=Math.min(1,(t-t0)/d),e=1-Math.pow(1-k,3);el.textContent=fmt(k<1?from+(val-from)*e:val);if(k<1)requestAnimationFrame(f)})(t0);\n}\nvar FX={debt:['💸','🪙','💵','✨'],pay:['🪙','✨','💰'],close:['🎉','✨','🪙','💛','🎊'],deliver:['📦','✨','🎁'],note:['📌','💛','✨','💜'],box:['📦','✨','➕']};\nfunction burst(kind,x,y){\n  if(RM||!document.body.animate)return;\n  var set=FX[kind]||FX.pay,n=kind==='close'?26:16;\n  x=x==null?innerWidth/2:x;y=y==null?innerHeight*.42:y;\n  for(var i=0;i<n;i++){(function(i){\n    var e=document.createElement('span');e.className='fx';e.textContent=set[i%set.length];document.body.appendChild(e);\n    var a=Math.random()*Math.PI*2,r=80+Math.random()*140,dx=Math.cos(a)*r,dy=Math.sin(a)*r-70,rot=(Math.random()-.5)*560,sc=.7+Math.random()*.8;\n    var p=function(px,py,ro,s){return 'translate('+(px-13)+'px,'+(py-13)+'px) rotate('+ro+'deg) scale('+s+')'};\n    e.animate([{transform:p(x,y,0,.2),opacity:1},{transform:p(x+dx,y+dy,rot/2,sc),opacity:1,offset:.5},{transform:p(x+dx*1.25,y+dy+170,rot,sc*.8),opacity:0}],\n      {duration:1100+Math.random()*600,delay:i*12,easing:'cubic-bezier(.2,.7,.3,1)',fill:'both'}).onfinish=function(){e.remove()};\n  })(i)}\n}\nvar ct;function celebrate(pic,text){\n  if(RM)return;var c=$('cele');c.querySelector('.cpic').style.backgroundImage=img(pic);c.querySelector('b').textContent=text;\n  c.classList.remove('on');void c.offsetWidth;c.classList.add('on');clearTimeout(ct);ct=setTimeout(function(){c.classList.remove('on')},1500);\n}\nfunction hop(el){el.classList.remove('hop');void el.offsetWidth;el.classList.add('hop')}\nvar splashDone=false,entered=false;\nfunction maybeShow(){if(splashDone&&entered)$('app').classList.add('show')}\n\nfunction fail(e,pic){toast(e&&e.message?e.message:String(e),pic||'delprod')}\nfunction openSheet(pic,title,body){\n  $('sheet').innerHTML='<div class=\"grab\"></div><div class=\"hd\"><div class=\"pic\" style=\"background-image:'+img(pic)+'\"></div><h3>'+esc(title)+'</h3></div>'+body;\n  $('scrim').classList.add('on');$('sheet').classList.add('on');$('sheet').scrollTop=0;\n}\nfunction closeSheet(){$('scrim').classList.remove('on');$('sheet').classList.remove('on')}\n$('scrim').onclick=closeSheet;\nfunction busy(btn,on){if(!btn)return;btn.disabled=on;btn.style.opacity=on?.6:1}\nfunction guard(btn,fn){return function(){if(btn.disabled)return;busy(btn,true);Promise.resolve().then(fn).then(function(){busy(btn,false)},function(e){busy(btn,false);fail(e)})}}\n\n/* ---------- data model ---------- */\nfunction nm(id){var m=S.members.filter(function(x){return x.user_id===id})[0];return m?m.display_name:'—'}\nfunction other(){return S.members.filter(function(x){return x.user_id!==S.uid})[0]||null}\nfunction dview(d){\n  var list=S.pays.filter(function(p){return p.debt_id===d.id});\n  var sum=r2(list.reduce(function(s,p){return s+Number(p.amount)},0)),amt=r2(d.amount);\n  var done=d.status==='paid'||sum>=amt;\n  return {d:d,amt:amt,paid:done?amt:sum,rem:done?0:r2(amt-sum),done:done,pays:list};\n}\nfunction snapshot(){return {mem:S.mem,members:S.members,debts:S.debts,pays:S.pays,prods:S.prods,msgs:S.msgs}}\nfunction cacheSave(){if(S.uid)lsSet(CACHE_PREFIX+S.uid,snapshot())}\n\n/* ---------- render ---------- */\nfunction render(){\n  var me=S.uid;\n  $('whoBtn').innerHTML=S.mem?('👤 '+esc(nm(me))+' ▾<i class=\"dot '+(S.sync===true?'ok':S.sync===false?'bad':'')+'\"></i>'):'';\n  var views=S.debts.map(dview),open=views.filter(function(v){return !v.done});\n  var iowe=0,owed=0;\n  open.forEach(function(v){if(v.d.debtor_id===me)iowe+=v.rem;else if(v.d.creditor_id===me)owed+=v.rem});\n  countTo($('sIowe'),r2(iowe),money);countTo($('sOwed'),r2(owed),money);\n  var bal=r2(owed-iowe),b=$('sBal');countTo(b,bal,function(v){v=r2(v);return (v>0?'+':v<0?'−':'')+money(Math.abs(v))});b.className=bal>0?'pos':bal<0?'neg':'';\n  $('cDebts').textContent=open.length;\n\n  var h='';\n  if(S.mem&&S.members.length<2){\n    h+='<div class=\"card invite\" id=\"inviteCard\"><div class=\"row\"><div class=\"dir\" style=\"background:linear-gradient(135deg,#aef0ff,#3aa8ff)\">👋</div><div class=\"grow\"><div class=\"t\">החבר עוד לא הצטרף</div><div class=\"s\">שלח לו את קוד ההזמנה: <b style=\"font-size:15px;letter-spacing:1px\">'+esc(S.mem.group.invite_code)+'</b></div></div><span class=\"badge\">שתף</span></div></div>';\n  }\n  open.sort(function(a,b){return String(b.d.created_at).localeCompare(String(a.d.created_at))}).forEach(function(v,i){\n    var mine=v.d.debtor_id===me,pct=Math.min(100,v.paid/v.amt*100);\n    h+='<div class=\"card'+(S.fresh[v.d.id]?' fresh':'')+'\" data-debt=\"'+v.d.id+'\" style=\"animation-delay:'+(i*.04)+'s\"><div class=\"row\"><div class=\"dir '+(mine?'out':'in')+'\">'+(mine?'↗':'↙')+'</div>'+\n      '<div class=\"grow\"><div class=\"t\">'+(mine?'אני חייב ל'+esc(nm(v.d.creditor_id)):esc(nm(v.d.debtor_id))+' חייב לי')+'</div><div class=\"s\">'+esc(v.d.description||'ללא תיאור')+' · '+fdate(v.d.created_at)+'</div></div>'+\n      '<div class=\"amt '+(mine?'out':'in')+'\">'+money(v.rem)+'</div></div>'+\n      (v.paid>0?'<div class=\"bar\"><i style=\"width:'+pct+'%\"></i></div><div class=\"s\" style=\"margin-top:5px\">שולם '+money(v.paid)+' מתוך '+money(v.amt)+'</div>':'')+'</div>';\n  });\n  if(!open.length)h+='<div class=\"empty\"><div class=\"pic\" style=\"background-image:'+img('closeddebt')+'\"></div><b>אין חובות פתוחים</b><span>הכול סגור בין שניכם 🎉</span></div>';\n  $('debts').innerHTML=h;\n\n  var pend=S.prods.filter(function(p){return !p.delivered});\n  $('cProds').textContent=pend.length;\n  h='';\n  pend.forEach(function(p,i){\n    h+='<div class=\"card'+(S.fresh[p.id]?' fresh':'')+'\" data-prod=\"'+p.id+'\" style=\"animation-delay:'+(i*.04)+'s\"><div class=\"row\"><div class=\"dir\" style=\"background:linear-gradient(135deg,#ffe9a8,#ffb800)\">📦</div>'+\n      '<div class=\"grow\"><div class=\"t\">'+esc(p.name)+' <span class=\"badge\">×'+esc(p.quantity)+'</span></div><div class=\"s\">'+(p.holder_id?'אצל '+esc(nm(p.holder_id)):'לא צוין אצל מי')+(p.receiver_id?' ← בדרך אל '+esc(nm(p.receiver_id)):'')+'</div></div>'+\n      '<span class=\"badge\">ממתין</span></div></div>';\n  });\n  if(!pend.length)h='<div class=\"empty\"><div class=\"pic\" style=\"background-image:'+img('product')+'\"></div><b>אין מוצרים בדרך</b><span>הכול נמסר 📦</span></div>';\n  $('prods').innerHTML=h;\n\n  var hidden=lsGet(HIDE_KEY)||[];\n  var notes=S.msgs.filter(function(n){return n.kind==='message'&&n.body&&hidden.indexOf(n.id)<0}).slice(0,8);\n  $('notesWrap').innerHTML=notes.length?'<div class=\"notes\">'+notes.map(function(n,i){\n    var c=0;for(var k=0;k<n.id.length;k++)c=(c+n.id.charCodeAt(k))%4;\n    return '<div class=\"note n'+c+'\" data-note=\"'+n.id+'\" style=\"animation-delay:'+(i*.05)+'s\"><span class=\"pin\">📌</span><div>'+esc(n.body)+'</div><small>מאת '+esc(nm(n.sender_id))+'</small></div>'}).join('')+'</div>':'';\n}\n\n/* ---------- loading / sync ---------- */\nvar loading=false,again=false,qt;\nfunction queueLoad(){clearTimeout(qt);qt=setTimeout(load,250)}\nasync function load(){\n  if(!S.mem)return;\n  if(loading){again=true;return}\n  loading=true;\n  try{\n    var d=await call('load',{groupId:S.mem.group.id});\n    var had={},fresh={};S.debts.concat(S.prods).forEach(function(x){had[x.id]=1});\n    if(S.loadedOnce)d.debts.concat(d.products).forEach(function(x){if(!had[x.id])fresh[x.id]=1});\n    S.members=d.members;S.debts=d.debts;S.pays=d.payments;S.prods=d.products;S.msgs=d.messages;\n    S.mem.members=d.members;S.sync=true;S.loadedOnce=true;S.fresh=fresh;cacheSave();\n  }catch(e){S.sync=false;S.lastError=e.message}\n  loading=false;render();S.fresh={};\n  if(again){again=false;load()}\n}\nasync function act(op,args,okMsg,pic,fx){\n  await call(op,args);\n  closeSheet();toast(okMsg,pic);\n  if(fx){setTimeout(function(){burst(fx)},150);\n    if(fx==='close')celebrate('closeddebt','החוב נסגר! 🎉');\n    else if(fx==='deliver')celebrate('product','המוצר נמסר! 📦');}\n  await load();\n}\n\n/* ---------- gate (login / group) ---------- */\nfunction gate(kind,msg){\n  var g=$('gate'),c=$('gateCard');g.classList.add('on');\n  function inp(id,ph,type,val){return '<input class=\"inp\" id=\"'+id+'\" placeholder=\"'+ph+'\" type=\"'+(type||'text')+'\" value=\"'+esc(val||'')+'\" autocomplete=\"off\" style=\"margin-bottom:10px\">'}\n  if(kind==='loading'){c.innerHTML='<div class=\"t\" style=\"font-size:17px\">טוען…</div>';return}\n  if(kind==='error'){\n    c.innerHTML='<div class=\"t\" style=\"font-size:18px;white-space:normal\">לא הצלחנו להתחבר</div><div class=\"s\" style=\"font-size:14px;margin:6px 0 4px;white-space:normal\">'+esc(msg||'')+'</div><button class=\"cta\" id=\"gRetry\">נסה שוב</button>';\n    $('gRetry').onclick=function(){boot()};return;\n  }\n  if(kind==='auth'){\n    var up=!!msg;\n    c.innerHTML='<div class=\"t\" style=\"font-size:20px;margin-bottom:12px;white-space:normal\">'+(up?'פותחים משתמש חדש':'ברוכים השבים')+'</div>'+inp('gEmail','אימייל','email')+inp('gPass','סיסמה (לפחות 6 תווים)','password')+\n      '<button class=\"cta\" id=\"gGo\" style=\"margin-top:6px\">'+(up?'הרשמה':'התחברות')+'</button><button class=\"cta ghost\" id=\"gSw\">'+(up?'יש לי משתמש — התחברות':'אין לי משתמש — הרשמה')+'</button>';\n    $('gSw').onclick=function(){gate('auth',!up)};\n    var go=$('gGo');go.onclick=guard(go,async function(){\n      var email=$('gEmail').value.trim(),pw=$('gPass').value;\n      if(!email||pw.length<6){toast('יש להזין אימייל וסיסמה (לפחות 6 תווים)','opendebt');return}\n      var s=await call(up?'signUp':'signIn',{email:email,password:pw});\n      S.uid=s.uid;S.email=s.email;await afterAuth();\n    });\n    return;\n  }\n  if(kind==='group'){\n    c.innerHTML='<div class=\"t\" style=\"font-size:20px;margin-bottom:4px;white-space:normal\">בואו נתחיל</div><div class=\"s\" style=\"font-size:13px;margin-bottom:12px;white-space:normal\">איך קוראים לך? כך יראו אותך באפליקציה.</div>'+inp('gName','דוד / אלי')+\n      '<label>אני הראשון — פותחים קבוצה חדשה</label>'+inp('gGroup','שם הקבוצה','text','דוד ואלי')+'<button class=\"cta\" id=\"gNew\" style=\"margin-top:0\">יצירת קבוצה</button>'+\n      '<label style=\"margin-top:18px\">קיבלתי קוד הזמנה מהשני</label>'+inp('gCode','קוד הזמנה')+'<button class=\"cta ghost\" id=\"gJoin\" style=\"margin-top:0\">הצטרפות</button><button class=\"cta ghost\" id=\"gOut\" style=\"color:#e0294d\">התנתקות</button>';\n    function need(){var d=$('gName').value.trim();if(!d)toast('יש להזין את השם שלך','opendebt');return d}\n    var n=$('gNew');n.onclick=guard(n,async function(){var d=need();if(!d)return;S.mem=await call('createGroup',{name:$('gGroup').value,display:d});await enter()});\n    var j=$('gJoin');j.onclick=guard(j,async function(){var d=need();if(!d)return;var code=$('gCode').value.trim();if(!code){toast('יש להזין קוד הזמנה','opendebt');return}S.mem=await call('joinGroup',{code:code,display:d});await enter()});\n    $('gOut').onclick=signOut;\n  }\n}\nfunction hideGate(){var g=$('gate');if(!g.classList.contains('on'))return;g.classList.add('leave');setTimeout(function(){g.classList.remove('on','leave')},450)}\nasync function signOut(){try{await call('signOut',{})}catch(e){}S.uid=S.email=S.mem=null;S.members=S.debts=S.pays=S.prods=S.msgs=[];S.sync=null;closeSheet();entered=false;$('app').classList.remove('show');render();gate('auth')}\n\nasync function enter(){\n  S.members=S.mem.members||[];hideGate();render();entered=true;maybeShow();\n  call('subscribe',{groupId:S.mem.group.id}).catch(function(){});\n  await load();\n}\nasync function afterAuth(){\n  var mem=await call('membership',{},15000);\n  if(!mem){gate('group');return}\n  S.mem=mem;await enter();\n}\nasync function boot(){\n  gate('loading');\n  var s;\n  try{s=await call('session',{},10000)}catch(e){gate('error',e.message);return}\n  if(!s){gate('auth');return}\n  S.uid=s.uid;S.email=s.email;\n  var c=lsGet(CACHE_PREFIX+s.uid),mem;\n  try{mem=await call('membership',{},15000)}\n  catch(e){\n    if(c&&c.mem){mem=c.mem;S.debts=c.debts||[];S.pays=c.pays||[];S.prods=c.prods||[];S.msgs=c.msgs||[];S.sync=false}\n    else{gate('error',e.message);return}\n  }\n  if(!mem){gate('group');return}\n  S.mem=mem;\n  if(c&&c.mem&&S.sync!==false){S.debts=c.debts||[];S.pays=c.pays||[];S.prods=c.prods||[];S.msgs=c.msgs||[]}\n  await enter();\n}\n\n/* ---------- debt ---------- */\nfunction debtForm(d){\n  var o=other();\n  if(!o){toast('החבר עוד לא הצטרף. שלח לו את קוד ההזמנה','opendebt');return}\n  d=d||{};var iowe=d.debtor_id?d.debtor_id===S.uid:true,dir={iowe:iowe};\n  openSheet('opendebt',d.id?'עריכת חוב':'חוב חדש',\n    '<label>סכום (₪)</label><input class=\"inp\" id=\"fAmt\" type=\"number\" inputmode=\"decimal\" min=\"0\" placeholder=\"0\" value=\"'+(d.amount||'')+'\">'+\n    '<label>מי חייב למי</label><div class=\"seg\" id=\"fDir\"><button data-v=\"1\" class=\"'+(iowe?'on':'')+'\">אני חייב ל'+esc(o.display_name)+'</button><button data-v=\"0\" class=\"'+(iowe?'':'on')+'\">'+esc(o.display_name)+' חייב לי</button></div>'+\n    '<label>עבור מה</label><input class=\"inp\" id=\"fWhy\" placeholder=\"למשל: ארוחת צהריים\" value=\"'+esc(d.description||'')+'\">'+\n    '<label>תאריך</label><input class=\"inp\" id=\"fDate\" type=\"date\" value=\"'+ymd(d.created_at)+'\">'+\n    '<button class=\"cta\" id=\"fSave\">'+(d.id?'שמור שינויים':'הוסף חוב')+'</button>');\n  $('fDir').onclick=function(e){var b=e.target.closest('button');if(!b)return;dir.iowe=b.dataset.v==='1';[].forEach.call($('fDir').children,function(x){x.classList.toggle('on',x===b)})};\n  var sv=$('fSave');sv.onclick=guard(sv,async function(){\n    var a=parseFloat($('fAmt').value);if(!(a>0)){$('fAmt').focus();toast('צריך להזין סכום','opendebt');return}\n    var debtor=dir.iowe?S.uid:o.user_id,creditor=dir.iowe?o.user_id:S.uid;\n    var dt=$('fDate').value,created=dt?new Date(dt+'T12:00:00').toISOString():null;\n    if(d.id){\n      var patch={amount:r2(a),creditor_id:creditor,debtor_id:debtor,description:$('fWhy').value.trim()};\n      if(created&&ymd(d.created_at)!==dt)patch.created_at=created;\n      await act('updateDebt',{id:d.id,patch:patch},'החוב עודכן','opendebt');\n    }else await act('addDebt',{groupId:S.mem.group.id,creditor_id:creditor,debtor_id:debtor,amount:r2(a),description:$('fWhy').value.trim(),created_at:created},'החוב נוסף','opendebt','debt');\n  });\n}\nfunction debtActions(id){\n  var d=S.debts.filter(function(x){return x.id===id})[0];if(!d)return;\n  var v=dview(d),mine=d.debtor_id===S.uid;\n  openSheet('opendebt',mine?'אני חייב ל'+nm(d.creditor_id):nm(d.debtor_id)+' חייב לי',\n    '<div class=\"row\" style=\"justify-content:space-between\"><div><div class=\"s\">נותר לתשלום</div><div class=\"amt '+(mine?'out':'in')+'\" style=\"font-size:32px\">'+money(v.rem)+'</div></div><div class=\"s\" style=\"text-align:left\">'+esc(d.description||'')+'<br>'+fdate(d.created_at)+'</div></div>'+\n    '<label>תשלום חלקי (₪)</label><div class=\"two\" style=\"grid-template-columns:1fr auto\"><input class=\"inp\" id=\"pAmt\" type=\"number\" inputmode=\"decimal\" placeholder=\"סכום\"><button class=\"cta\" id=\"pGo\" style=\"margin:0;padding:0 20px;font-size:16px\">עדכן</button></div>'+\n    (v.pays.length?'<div class=\"hist\">'+v.pays.map(function(p){return '<div><span>'+fdate(p.created_at)+' · '+esc(nm(p.paid_by))+'</span><span>'+money(p.amount)+'</span></div>'}).join('')+'</div>':'')+\n    '<button class=\"cta\" id=\"aPaid\">סמן כשולם במלואו ✓</button>'+\n    '<div class=\"two\"><button class=\"cta ghost\" id=\"aEdit\">עריכה</button><button class=\"cta ghost\" id=\"aDel\" style=\"color:#e0294d\">מחיקה</button></div>');\n  var pg=$('pGo');pg.onclick=guard(pg,async function(){\n    var a=parseFloat($('pAmt').value);if(!(a>0)){$('pAmt').focus();return}\n    a=Math.min(r2(a),v.rem);\n    await act('recordPayment',{debtId:d.id,amount:a},a>=v.rem?'החוב נסגר!':'התשלום נרשם. נותר '+money(v.rem-a),a>=v.rem?'closeddebt':'opendebt',a>=v.rem?'close':'pay');\n  });\n  var pd=$('aPaid');pd.onclick=guard(pd,function(){return act('recordPayment',{debtId:d.id,amount:v.rem},'החוב נסגר!','closeddebt','close')});\n  $('aEdit').onclick=function(){debtForm(d)};\n  var dl=$('aDel');dl.onclick=guard(dl,async function(){\n    if(!dl.dataset.sure){dl.dataset.sure=1;dl.textContent='לחץ שוב למחיקה';return}\n    await act('deleteDebt',{id:d.id},'החוב נמחק','close');\n  });\n}\n\n/* ---------- product ---------- */\nfunction prodForm(p){\n  var o=other();p=p||{};\n  var holder=p.holder_id||S.uid,rec=p.receiver_id||(o?o.user_id:S.uid);\n  function opts(v){return S.members.map(function(m){return '<option value=\"'+m.user_id+'\"'+(m.user_id===v?' selected':'')+'>'+esc(m.display_name)+'</option>'}).join('')}\n  openSheet('addprod',p.id?'עריכת מוצר':'מוצר חדש',\n    '<label>שם המוצר</label><input class=\"inp\" id=\"mName\" placeholder=\"למשל: מטען לאייפון\" value=\"'+esc(p.name||'')+'\">'+\n    '<label>כמות</label><input class=\"inp\" id=\"mQty\" type=\"number\" inputmode=\"numeric\" min=\"1\" value=\"'+(p.quantity||1)+'\">'+\n    '<div class=\"two\"><div><label>אצל מי</label><select class=\"inp\" id=\"mHold\">'+opts(holder)+'</select></div><div><label>למי מיועד</label><select class=\"inp\" id=\"mRec\">'+opts(rec)+'</select></div></div>'+\n    '<button class=\"cta\" id=\"mSave\">'+(p.id?'שמור שינויים':'הוסף מוצר')+'</button>'+\n    (p.id?'<div class=\"two\"><button class=\"cta ghost\" id=\"mDel\" style=\"color:#e0294d\">מחיקה</button><button class=\"cta ghost\" id=\"mDone\">נמסר ✓</button></div>':''));\n  $('mHold').onchange=function(){var x=S.members.filter(function(m){return m.user_id!==$('mHold').value})[0];if(x)$('mRec').value=x.user_id};\n  var sv=$('mSave');sv.onclick=guard(sv,async function(){\n    var n=$('mName').value.trim();if(!n){$('mName').focus();toast('צריך שם למוצר','product');return}\n    var row={name:n,quantity:Math.max(1,parseInt($('mQty').value,10)||1),holder_id:$('mHold').value,receiver_id:$('mRec').value};\n    if(p.id)await act('updateProduct',{id:p.id,patch:row},'המוצר עודכן','addprod');\n    else await act('addProduct',Object.assign({groupId:S.mem.group.id},row),'המוצר נוסף','addprod','box');\n  });\n  if(p.id){\n    var dn=$('mDone');dn.onclick=guard(dn,function(){return act('updateProduct',{id:p.id,patch:{delivered:true}},'המוצר נמסר!','closeddebt','deliver')});\n    var dl=$('mDel');dl.onclick=guard(dl,async function(){if(!dl.dataset.sure){dl.dataset.sure=1;dl.textContent='לחץ שוב למחיקה';return}await act('deleteProduct',{id:p.id},'המוצר נמחק','delprod')});\n  }\n}\nfunction prodActions(id){\n  var p=S.prods.filter(function(x){return x.id===id})[0];if(!p)return;\n  openSheet('product',p.name,\n    '<div class=\"s\" style=\"font-size:14px\">כמות: <b>'+esc(p.quantity)+'</b><br>נמצא אצל: <b>'+esc(p.holder_id?nm(p.holder_id):'—')+'</b><br>מיועד ל: <b>'+esc(p.receiver_id?nm(p.receiver_id):'—')+'</b></div>'+\n    '<button class=\"cta\" id=\"xDone\">סמן כנמסר ✓</button><button class=\"cta ghost\" id=\"xEdit\">עריכה / מחיקה</button>');\n  var dn=$('xDone');dn.onclick=guard(dn,function(){return act('updateProduct',{id:p.id,patch:{delivered:true}},'המוצר נמסר!','closeddebt','deliver')});\n  $('xEdit').onclick=function(){prodForm(p)};\n}\n\n/* ---------- note (thank-you note, shared with the other user) ---------- */\nfunction noteForm(){\n  var o=other();\n  if(!o){toast('החבר עוד לא הצטרף. שלח לו את קוד ההזמנה','notes');return}\n  openSheet('notes','פתק תודה',\n    '<div class=\"s\" style=\"font-size:13px\">הפתק יופיע במסך הבית שלך ושל '+esc(o.display_name)+'</div>'+\n    '<label>הטקסט</label><textarea class=\"inp\" id=\"nTxt\" rows=\"3\" maxlength=\"80\" placeholder=\"תודה על הקפה! ☕\"></textarea>'+\n    '<button class=\"cta\" id=\"nSave\">נעץ במסך הבית 📌</button>');\n  var sv=$('nSave');sv.onclick=guard(sv,async function(){\n    var t=$('nTxt').value.trim();if(!t){$('nTxt').focus();return}\n    await act('sendNote',{groupId:S.mem.group.id,recipient_id:o.user_id,body:t},'הפתק ננעץ','notes','note');\n  });\n}\nfunction noteView(id){\n  var n=S.msgs.filter(function(x){return x.id===id})[0];if(!n)return;\n  openSheet('notes','פתק מ'+nm(n.sender_id),'<div class=\"card\" style=\"box-shadow:none;background:#fff8c8;font-weight:800;font-size:17px;line-height:1.4\">'+esc(n.body)+'</div><div class=\"s\">'+fdate(n.created_at)+'</div><button class=\"cta ghost\" id=\"nHide\">הסר מהמסך שלי</button>');\n  $('nHide').onclick=function(){var h=lsGet(HIDE_KEY)||[];h.push(id);lsSet(HIDE_KEY,h);closeSheet();render();toast('הפתק הוסר מהמסך','close')};\n}\n\n/* ---------- account ---------- */\nfunction accountSheet(){\n  if(!S.mem)return;\n  openSheet('settings',nm(S.uid),\n    '<div class=\"s\" style=\"font-size:13px;direction:ltr;text-align:right\">'+esc(S.email||'')+'</div><div class=\"s\" style=\"font-size:13px;margin-top:6px;font-weight:800;color:'+(S.sync===true?'#0b7d4d':'#c01540')+'\">'+(S.sync===true?'● מסונכרן עם השרת':'● לא מסונכרן'+(S.lastError?': '+esc(S.lastError):''))+'</div>'+\n    '<label>קוד הזמנה לקבוצה \"'+esc(S.mem.group.name)+'\"</label><div class=\"amt\" style=\"font-size:24px;text-align:right;letter-spacing:2px\">'+esc(S.mem.group.invite_code)+'</div>'+\n    '<button class=\"cta ghost\" id=\"aShare\">שתף קוד הזמנה</button><button class=\"cta ghost\" id=\"aOut\" style=\"color:#e0294d\">התנתקות</button>');\n  $('aShare').onclick=function(){call('share',{text:'הצטרף אלי ל-DALI PAY. קוד הזמנה: '+S.mem.group.invite_code}).catch(fail)};\n  $('aOut').onclick=signOut;\n}\n\n/* ---------- events ---------- */\n$('bDebt').onclick=function(){hop(this);debtForm()};\n$('bProd').onclick=function(){hop(this);prodForm()};\n$('bNote').onclick=function(){hop(this);noteForm()};\n$('debts').onclick=function(e){\n  if(e.target.closest('#inviteCard')){accountSheet();return}\n  var c=e.target.closest('[data-debt]');if(c)debtActions(c.dataset.debt)};\n$('prods').onclick=function(e){var c=e.target.closest('[data-prod]');if(c)prodActions(c.dataset.prod)};\n$('notesWrap').onclick=function(e){var c=e.target.closest('[data-note]');if(c)noteView(c.dataset.note)};\n$('whoBtn').onclick=accountSheet;\ndocument.addEventListener('visibilitychange',function(){if(!document.hidden)queueLoad()});\n\nrender();boot();\nsetTimeout(function(){$('splash').classList.add('out');setTimeout(function(){splashDone=true;maybeShow()},window.DP_SPLASH_MS?0:350)},window.DP_SPLASH_MS||2700);\n})();\n\n</script>\n</body>\n</html>\n";
